async () => {
  const res = await fetch('/api/documents/incident-alpha');
  const data = await res.json();
  const content = data.content || data.text || JSON.stringify(data).slice(0,200);
  const lines = content.split('\n');
  const idx0600 = lines.findIndex(l => l.includes('ALPHA-0600'));
  return {
    keys: Object.keys(data),
    revision: data.revision,
    totalLines: lines.length,
    idx0600,
    line0600: lines[idx0600],
    lastLine: lines[lines.length-1],
    secondLastLine: lines[lines.length-2],
  };
}

