async () => {
  const res = await fetch('/api/documents/incident-alpha');
  const data = await res.json();
  const content = data.content;
  function countOcc(s, sub) {
    let count = 0, idx = 0;
    while ((idx = s.indexOf(sub, idx)) !== -1) { count++; idx += sub.length; }
    return count;
  }
  return {
    revision: data.revision,
    LOCATION_ONE: countOcc(content, 'LOCATION-ONE'),
    LOCATION_TWO: countOcc(content, 'LOCATION-TWO'),
    LOCATION_THREE: countOcc(content, 'LOCATION-THREE'),
    line1: content.split('\n')[0],
    lastLine: content.split('\n').slice(-1)[0],
  };
}

